package id.duakelinci.dashboard;
import static org.assertj.core.api.Assertions.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockMultipartFile;
class ImportServiceTest{
 Path root,base;SalesCsvParser parser;CsvSalesRepository repo;ImportService service;
 @BeforeEach void setup()throws Exception{root=Files.createTempDirectory("import-test");base=root.resolve("sales.csv");Files.writeString(base,csv("2026-01-01,I0,R0,B0,O0,Default,X,1,100,0,100"));parser=new SalesCsvParser(100000);repo=new CsvSalesRepository(base.toString(),root.resolve("runtime").toString(),parser);service=new ImportService(parser,repo,root.resolve("runtime").toString(),10_485_760,30);}
 @AfterEach void cleanup()throws Exception{try(var files=Files.walk(root)){files.sorted(java.util.Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(Exception ignored){}});}}
 @Test void previewsPartialRowsAndRequiresConsentThenReplacesDataset()throws Exception{String content=csv("2026-02-01,I1,R1,B1,O1,Outlet \"Satu\",Y,2,200,20,180\n2026-02-02,I2,R1,B1,O2,Buruk,Y,-1,100,0,100");var upload=new MockMultipartFile("file","../../baru.csv","text/csv",content.getBytes(StandardCharsets.UTF_8));var p=service.preview(upload);assertThat(p.originalFileName()).isEqualTo("baru.csv");assertThat(p.validRows()).isEqualTo(1);assertThat(p.rejectedRows()).isEqualTo(1);assertThatThrownBy(()->service.activate(new ApiModels.ActivateImportRequest(p.previewId(),false,p.checksumSha256()))).isInstanceOf(ImportService.ImportException.class);var m=service.activate(new ApiModels.ActivateImportRequest(p.previewId(),true,p.checksumSha256()));assertThat(m.sourceType()).isEqualTo("IMPORT");assertThat(repo.snapshot().records()).hasSize(1);assertThatThrownBy(()->service.activate(new ApiModels.ActivateImportRequest(p.previewId(),true,p.checksumSha256()))).isInstanceOf(ImportService.ImportException.class);}
 @Test void supportsBomCrLfAndQuotedMultiline()throws Exception{String body="\ufeff"+csv("2026-02-01,I1,R1,B1,O1,\"Outlet\r\nSatu\",Y,1,100,0,100").replace("\n","\r\n");var p=service.preview(new MockMultipartFile("file","bom.csv","text/csv",body.getBytes(StandardCharsets.UTF_8)));assertThat(p.validRows()).isEqualTo(1);assertThat(p.outletCount()).isEqualTo(1);}
 @Test void rejectsMissingHeaderWithoutChangingActiveData(){String bad="date,invoice_no\n2026-01-01,I1\n";assertThatThrownBy(()->service.preview(new MockMultipartFile("file","bad.csv","text/csv",bad.getBytes(StandardCharsets.UTF_8)))).isInstanceOfSatisfying(ImportService.ImportException.class,e->{assertThat(e.status).isEqualTo(400);assertThat(e.errors).extracting(ApiModels.ValidationError::code).contains("MISSING_HEADER");});assertThat(repo.snapshot().records()).hasSize(1);}
 static String csv(String rows){return"date,invoice_no,region,branch,outlet_id,outlet_name,brand,qty_carton,gross_sales_idr,discount_idr,net_sales_idr\n"+rows+"\n";}
}
